enum class LiteralSupport : uint8_t {
  None = 0,
  Literal32 = 1,
  Literal64 = 2,
  Both = 3,
};

[[nodiscard]] constexpr bool supports_literal(LiteralSupport support, LiteralSupport required) {
  return (static_cast<uint8_t>(support) & static_cast<uint8_t>(required)) != 0;
}

